use crate::aap::caps::kb_read;
use crate::aap::caps::tool_llm::{self, Reply};
use crate::aap::caps::types::Intent;

const SYSTEM: &str = "You are a customer support assistant. Answer the question \
using the intent and knowledge provided. If you need more information, call the \
`lookup` tool to search the knowledge base.";

/// Upper bound on tool-orchestration rounds, so a model that keeps asking for
/// tools cannot loop forever.
const MAX_TOOL_ROUNDS: usize = 4;

fn intent_label(intent: Intent) -> &'static str {
    match intent {
        Intent::BillingQuestion => "billing-question",
        Intent::TechnicalSupport => "technical-support",
        Intent::AccountChange => "account-change",
        Intent::GeneralInquiry => "general-inquiry",
        Intent::Unknown => "unknown",
    }
}

fn error(message: impl Into<String>) -> ResponseResult {
    ResponseResult::Error(LlmError {
        message: message.into(),
    })
}

struct Node;

impl Guest for Node {
    fn run(ctx: ConversationContext) -> ResponseResult {
        let mut prompt = format!(
            "Intent: {}\nQuestion: {}\n\nKnowledge:\n{}",
            intent_label(ctx.intent),
            ctx.question,
            ctx.knowledge.join("\n"),
        );

        let mut rounds = 0usize;
        loop {
            match tool_llm::generate(SYSTEM, &prompt) {
                Reply::Text(text) => {
                    return ResponseResult::Ok(AgentResponse { text });
                }
                Reply::Call(req) => {
                    if rounds >= MAX_TOOL_ROUNDS {
                        return error("tool-call limit exceeded");
                    }
                    rounds += 1;

                    // The only tool in this node's scope is `lookup`, backed by
                    // kb-read. Any other tool name is refused as a value.
                    if req.tool != "lookup" {
                        return error(format!("tool not in scope: {}", req.tool));
                    }

                    let hits = kb_read::lookup(&req.query);
                    prompt.push_str(&format!(
                        "\n\nLookup {:?} returned:\n{}",
                        req.query,
                        hits.join("\n"),
                    ));
                }
            }
        }
    }
}

export!(Node);
